def match(orders):
    import heapq

    book_buy = []   # max-heap via negative price: (-price, seq, oid)
    book_sell = []  # min-heap: (price, seq, oid)
    order_info = {}  # id -> dict(side, price, qty, seq, cancelled)
    seq_counter = 0
    trades = []

    def push_resting(oid):
        info = order_info[oid]
        if info['side'] == 'buy':
            heapq.heappush(book_buy, (-info['price'], info['seq'], oid))
        else:
            heapq.heappush(book_sell, (info['price'], info['seq'], oid))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = order_info.get(oid)
            if info is None or info['qty'] <= 0 or info.get('cancelled'):
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info and info['qty'] > 0 and not info.get('cancelled'):
                info['cancelled'] = True
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq_counter += 1
        remaining = qty

        opp_heap = book_sell if side == 'buy' else book_buy

        while remaining > 0:
            top = top_valid(opp_heap)
            if top is None:
                break

            if side == 'buy':
                opp_price = top[0]
            else:
                opp_price = -top[0]

            if typ != 'market':
                if side == 'buy' and price < opp_price:
                    break
                if side == 'sell' and price > opp_price:
                    break

            # pop this resting order to process it
            heapq.heappop(opp_heap)
            oid2 = top[2]
            info2 = order_info[oid2]

            trade_qty = min(remaining, info2['qty'])
            if side == 'buy':
                trades.append([oid, oid2, info2['price'], trade_qty])
            else:
                trades.append([oid2, oid, info2['price'], trade_qty])

            remaining -= trade_qty
            info2['qty'] -= trade_qty

            if info2['qty'] > 0:
                heapq.heappush(opp_heap, top)
            # else it's fully filled, leave popped out

        if typ == 'limit' and remaining > 0:
            order_info[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'seq': seq_counter,
                'cancelled': False
            }
            push_resting(oid)
        # ioc/market discard remainder; no need to store info for them

    return trades

